mapper.select:
SELECT h.id AS "id", h.draft_id AS "draftId", h.version_id AS "versionId", h.version_label AS "versionLabel", h.kind AS "kind",
       h.quote_id AS "quoteId", h.requested_by_name AS "requestedByName", h.requested_by_username AS "requestedByUsername",
       h.created_at AS "createdAt", d.name AS "draftName", d.client_name AS "clientName",
       (SELECT lr.id FROM label_requests lr WHERE lr.handoff_id = h.id LIMIT 1) AS "labelRequestId",
       (SELECT lr.status FROM label_requests lr WHERE lr.handoff_id = h.id LIMIT 1) AS "labelStatus",
       (SELECT q.status FROM quotes q WHERE q.quote_id = h.quote_id) AS "quoteStatus"
FROM recipe_handoffs h LEFT JOIN recipe_drafts d ON d.id = h.draft_id
WHERE 1 = 1
AND h.draft_id = #{draftId}
AND h.kind = #{kind}
AND substr(h.created_at, 1, 10) >= #{start}
AND substr(h.created_at, 1, 10) <= #{end}
ORDER BY h.id DESC
